For each $\beta \in \mathbb R^+$ let $A_{\beta}$ denote the set of all $\alpha \in \mathbb R^+$ such that $\mathcal{M}$ contains an $(\alpha,\beta)$-good sequence.
  Let $B = \{\beta \in \mathbb R^+: A_\beta \ne \varnothing\}$. By assumption, $B$ is a nonempty interval with $\inf(B) = 0$ and $\sup(B) \le 1$; let $\beta_{\max} = \sup(B)$. Each nonempty $A_x$ is also such an interval; for each $x \in B$, let $\alpha_{\max}(x) = \sup(A_x)$, noting that $\alpha_{\max}(x) \le 1$. 

  Let $\beta \in (\tfrac{2}{3}\beta_{\max},\beta_{\max})$ and let $\delta = \tfrac{\beta}{4(1-\beta)}$. Set $\alpha_{\max} = \alpha_{\max}(\beta)$ and let $\alpha \in ((1+\tfrac{1}{2}\delta)^{-1}\alpha_{\max},\alpha_{\max})$. We have $\beta \in B$ and $\alpha \in A_{\beta}$; let $M_0, M_1, \dotsc$ be an $(\alpha,\beta)$-good sequence of matroids in $\mathcal{M}$. Since $2\beta > \beta_{\max}$ we have $2\beta \notin B$ so $A_{2\beta} = \varnothing$ and in particular $\tfrac{1}{2}\alpha \notin A_{2\beta}$. Moreover, we have $(1+\delta)\alpha > \alpha_{\max}$ so $(1+\delta)\alpha \notin A_\beta$. There are therefore integers $m_1$ and $m_2$ such that and every matroid $M \in \mathcal{M}$ with $|M| \ge m_1$ satisfies $g(M^*) < 2\beta |M|$ or $r(M) < \tfrac{1}{2}\alpha|M|$, and every matroid $M \in \mathcal{M}$ with $|M| \ge m_2$ satisfies $g(M^*) < \beta |M|$ or $r(M) < \alpha(1+\delta)|M|$. Let $m = \max(m_1,m_2,8t\alpha^{-1})$. 

  \begin{claim}
    For each $n \in \mathbb Z$ with $n \ge 2\beta^{-1}m$, the matroid $M_n$ is vertically $t$-connected. 
  \end{claim}
  \begin{proof}
    Suppose for a contradiction that $n \ge 2\beta^{-1}m$ and $M = M_n$ is not vertically $t$-connected. Let $(X_1,X_2)$ be a partition of $E(M)$ with $r_M(X_1) + r_M(X_2) = r(M) + t' - 1$ with $t' < t$ and $r_M(X_1),r_M(X_2) \ge t'$. Let $N_1 = M/ X_2$ and $N_2 = M / X_1$. Note that $N_1,N_2 \in \mathcal{M}$ and that $r(N_i) = r(M)-r_M(X_{3-i}) > r(M)-t+1$, so $r(N_1) + r(N_2) > r(M)-2t$. Since every cocircuit of $N_1$ or $N_2$ is a cocircuit of $M$, we have $g(M^*) \le \min(g(N_1^*),g(N_2^*))$.We have
        \[ \beta|M| \le g(M^*) \le \min(g(N_1^*),g(N_2^*)) \le \tfrac{1}{2}(g(N_1^*) + g(N_2^*))\]
    and, since $|M| = |N_1| + |N_2|$, we have either $g(N_1^*) \ge 2\beta|N_1|$ or $g(N_2^*) \ge 2\beta|N_2|$. We may assume that the first case holds. Since each of $X_1$ and $X_2$ contains a cocircuit of $M$, we have $|N_i| = |X_i| \ge g(M^*) \ge \beta|M| \ge m$ for each $i \in \{1,2\}$. Since $|N_1| + |N_2| = |M|$, this implies that $|N_1| \ge \tfrac{\beta}{1-\beta}|N_2|$. Moreover, $m \ge m_1$ gives $r(N_1) < \tfrac{1}{2}\alpha|N_1|$. We have 
    \begin{align*}
      \alpha|M| &\le r(M) \\
            &< r(N_1) + r(N_2) + 2t\\
            &< \tfrac{1}{2}\alpha|N_1| + r(N_2) + 2t\\
            &\le \tfrac{3}{4}\alpha|N_1| + r(N_2),
    \end{align*}
    Where the last line uses $\tfrac{1}{4}\alpha|N_1| \ge \tfrac{1}{4}\alpha m \ge 2t$. From this and $|M| = |N_1|+|N_2|$ we get 
    \begin{align*}
      r(N_2) &\ge \tfrac{1}{4}\alpha|N_1| + \alpha|N_2|\\
           &= \alpha\left(1 + \delta \right)|N_2|
    \end{align*} 
    Now $|N_2| \ge m \ge m_2$ so $g(N_2^*) < \beta |N_2|$ by choice of $m_2$. However $g(M^*) \le g(N_2^*)$ and $\beta|N_2| < \beta|M|$, so $g(M^*) < \beta|M|$, contradicting the definition of $M$.

Let $m = |E(G)|$ and $\alpha = 2(\log(1+\beta))^{-1}$. By choice of $n$ we have $\frac{t \alpha \log n}{n} < \tfrac{t \alpha}{\sqrt{n}} < \tfrac{1}{2}\beta$.
     Let $\mathcal{C}$ be a maximal collection of pairwise disjoint cycles of $G$ such that $|E(C)| \le \alpha \log n$ for each $C \in \mathcal{C}$. Assume for a contradiction that $|\mathcal{C}| < t$; let $G' = G \!\setminus\! \cup \mathcal{C}$. We have $\tfrac{|E(G')|}{n} \ge \tfrac{m - t\alpha \log(n)}{n} \ge 1+\beta - \tfrac{t \alpha \log(n)}{n} > 1 + \tfrac{1}{2}\beta$, so the average degree $\delta'$ of $G'$ is at least $2 + \beta$. By maximality of $\mathcal{C}$, the graph $G'$ has girth $g' > \alpha \log (n)$, so Lemma~\ref{moore} gives \begin{align*}
      \alpha \log(n)  &< 4 + \frac{\log(n)}{\log(\delta'-1)}  \le 4 + \frac{\log(n)}{\log(1+\beta).}
\end{align*}
  Rearranging gives $\log(n) < 4\log(1+\beta)$, contradicting $n \ge (1+\beta)e^4$.

Let $A$ be an $\mathbb F$-frame matrix generating $M$ and let $(G,\Sigma)$ be a graph representation of $A$. Pick a spanning tree $T$ of $G$. By repeatedly resigning, we may assume that the edges of $T$ have sign $1$. Note that $|E(T)| \geq r(M) - 1$.

     Let $G^+$ denote the undirected graph with vertex set $V(G) \times \mathbb F^\times$ and edge set 
     \begin{align*}
      & \{((\delta^{-}(e),\gamma),(\delta^{+}(e),\gamma)): e \in T, \gamma \in \mathbb F\}\\
      \cup & \{((\delta^-(e), 1), (\delta^+(e), \sign(e))): e \in E(G)\setminus T\};
     \end{align*}
      that is, we take $q-1$ copies of $T$, and each directed edge $(u,v)$ not in $T$ with sign $\gamma$ connects the copy of $T$ corresponding to $1$ with the copy of $T$ corresponding to $\gamma$.

It is easy to check that each cycle of $G^+$, by projection onto the first coordinate, corresponds to either a balanced cycle of $(G,\Sigma)$, or a subgraph of $G$ of minimum degree 2 that is not a cycle. It follows from Proposition~\ref{bicycledependent} that every cycle of $G^+$ is dependent in $M$. Now,
\begin{align*}
    |E(G^+)| & = (q-1)|E(T)| + |M| - |E(T)| \geq (q-2)(r(M) - 1) + |M|\\
    & \ge (q-1)(1+\beta)r(M) + \beta r(M) - (q-2)\\
    & \ge (1+\beta)|V(G^+)| - (q-1)(1+\beta) + \beta r(M) - q + 2\\
    &  \ge (1+\beta)|V(G^+)|,  
\end{align*}

     where we use $|E(T)| \geq r(M)-1$ first, $|M| \geq (1+q\beta)r(M)$ second, $|V(G^+)| \le (q-1)(r(M)+1)$ third, and $r(M) \ge (2q-3)\beta^{-1}+1-q$ last. By our lower bounds for $n = |V(G+)| \geq (q-1)r(M)$ and Lemma~\ref{disjointcircuits}, the graph $G^+$ contains $t$ pairwise disjoint cycles, each of size at most $\frac{2\log n}{\log(1+\beta)} \le \frac{4 \log r(M)}{\log(1+\beta)}$. Each of these cycles of $G$ is dependent in $M$, and it is thus easy to see that their union satisfies the result.

